<script setup>
import componentPages from './component-pages.json';
import ComponentExperience from './ComponentExperience.vue';
import { computed, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { App as AntApp } from 'ant-design-vue';
import { tasks, resources, logs, services, runDemoTask } from './data';
import Trend from './Trend.vue';
const route = useRoute(); const router = useRouter(); const { message } = AntApp.useApp();
const query = ref(''); const filter = ref('all'); const period = ref('7');
const createOpen = ref(false); const uploadOpen = ref(false); const previewOpen = ref(false); const selected = ref(null); const files = ref([]);
const draft = reactive({ name: '', app: 'demo-api', schedule: '每天 09:00' });
const defaults = { name:'WorkerKit 工作空间', description:'我的 Worker 应用与自动化任务', timezone:'Asia/Shanghai', retention:30, failureNotice:true, dailyDigest:false };
const settings = reactive({ ...defaults });
try { Object.assign(settings, JSON.parse(localStorage.getItem('workerkit-vben-settings') || '{}')); } catch {}
const names = { '/':'运行概览', '/tasks':'任务调度', '/resources':'资源管理', '/logs':'运行日志', '/settings':'应用设置' };
const descriptions = { '/':'从这里了解应用状态、任务执行与资源使用情况。', '/tasks':'管理自动化计划，查看执行状态，随时手动运行。', '/resources':'浏览图片、音视频和文档，统一管理应用中的资源。', '/logs':'按应用和级别查看执行事件，快速定位异常。', '/settings':'配置工作空间、显示偏好和通知选项。' };
const componentPage = computed(() => componentPages.find(page => page.path === route.path));
const activePath = computed(() => componentPage.value?.example || route.path);
Object.assign(names, Object.fromEntries(componentPages.map(page => [page.path, page.title])));
Object.assign(descriptions, Object.fromEntries(componentPages.map(page => [page.path, page.description])));
watch(() => route.path, () => { query.value='';filter.value='all';document.title=`WorkerKit · ${names[route.path]} · Vben`; }, { immediate:true });
const statuses = { success:['成功','success'], warning:['部分失败','warning'], paused:['已暂停','default'], running:['运行中','processing'] };
const types = { image:['图片','▧'], audio:['音频','♫'], video:['视频','▷'], document:['文档','≡'] };
const filteredTasks = computed(() => tasks.value.filter(t => `${t.name} ${t.app}`.includes(query.value) && (filter.value==='all'||(filter.value==='enabled'?t.enabled:!t.enabled))));
const filteredResources = computed(() => resources.value.filter(r => r.name.includes(query.value) && (filter.value==='all'||r.type===filter.value)));
const filteredLogs = computed(() => logs.value.filter(l => `${l.message} ${l.app}`.includes(query.value) && (filter.value==='all'||l.level===filter.value)));
const taskColumns = [{title:'任务名称',dataIndex:'name',key:'name',width:230,sorter:(a,b)=>a.name.localeCompare(b.name)}, {title:'应用',dataIndex:'app',key:'app'}, {title:'执行计划',dataIndex:'schedule',key:'schedule'}, {title:'最近结果',dataIndex:'status',key:'status'}, {title:'上次执行',dataIndex:'lastRun',key:'lastRun'}, {title:'启用',key:'enabled'}, {title:'操作',key:'actions'}];
const logColumns = [{title:'时间',dataIndex:'time'}, {title:'级别',dataIndex:'level',key:'level'}, {title:'应用',dataIndex:'app'}, {title:'事件内容',dataIndex:'message',width:500}, {title:'耗时',dataIndex:'duration'}];
async function run(t) { await runDemoTask(t); message.success('模拟执行完成'); }
function createTask(){tasks.value.unshift({id:Date.now(),name:draft.name.trim(),description:'新建演示任务',app:draft.app,schedule:draft.schedule,status:'paused',lastRun:'尚未执行',duration:'—',enabled:false});createOpen.value=false;draft.name='';message.success('演示任务已创建');}
function upload(){if(!files.value.length)return;if(files.value.some(f=>f.size>100*1024*1024)){message.error('单个文件不能超过 100 MB');return;}for(const entry of files.value){const file=entry.originFileObj||entry;const type=file.type.startsWith('image/')?'image':file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'document';resources.value.unshift({id:crypto.randomUUID(),name:file.name,type,size:`${Math.ceil(file.size/1024)} KB`,date:'刚刚',tag:'本地文件',local:true,url:URL.createObjectURL(file)});}files.value=[];uploadOpen.value=false;message.success('已加入本地文件，没有上传到服务器');}
function preview(r){selected.value=r;previewOpen.value=true;}
function save(){try{localStorage.setItem('workerkit-vben-settings',JSON.stringify(settings));message.success('演示设置已保存到当前浏览器');}catch{message.error('浏览器存储不可用');}}
function exportLogs(){const url=URL.createObjectURL(new Blob([JSON.stringify(filteredLogs.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='workerkit-demo-logs.json';a.click();URL.revokeObjectURL(url);}
</script>
<template>
  <div class="demo-page">
    <div class="demo-heading"><div><h1>{{ names[route.path] }}</h1><p>{{ descriptions[route.path] }}</p></div><AButton v-if="activePath==='/'" @click="router.push('/tasks')">查看任务 ↗</AButton><AButton v-if="activePath==='/tasks'" type="primary" @click="createOpen=true">＋ 新建任务</AButton><AButton v-if="activePath==='/resources'" type="primary" @click="uploadOpen=true">添加文件</AButton><AButton v-if="activePath==='/logs'" @click="exportLogs">导出日志</AButton></div>
    <ComponentExperience v-if="componentPage && !componentPage.example" :kind="componentPage.key" />
    <template v-if="activePath==='/'">
      <div class="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><ACard v-for="stat in [{label:'Worker 应用',value:'8',unit:'个',note:'7 个正常 · 1 个需关注'},{label:'今日任务执行',value:'124',unit:'次',note:'较昨日增加 18 次'},{label:'任务成功率',value:'98.4',unit:'%',note:'122 次成功 · 2 次异常'},{label:'资源存储',value:'1.28',unit:'GB',note:'已使用配额的 12.8%'}]" :key="stat.label"><AStatistic :title="stat.label" :value="stat.value" :value-style="{fontSize:'30px',fontWeight:600}" :suffix="stat.unit" /><p class="text-xs text-muted-foreground mt-4 mb-0">{{ stat.note }}</p></ACard></div>
      <div class="grid xl:grid-cols-[minmax(0,1.8fr)_minmax(280px,1fr)] gap-6 mb-6"><ACard><div class="flex justify-between gap-3"><div><h2 class="demo-section-title">请求趋势</h2><p class="text-xs text-muted-foreground">各应用请求量的示例分布</p></div><ASelect v-model:value="period" :options="[{label:'近 7 天',value:'7'},{label:'近 14 天',value:'14'}]" aria-label="趋势时间范围" style="width:110px" /></div><div class="flex items-center gap-3 my-5"><strong class="text-2xl">{{ period==='7'?'31,702':'64,518' }}</strong><span class="text-xs text-muted-foreground">次请求</span><ATag color="success">+12.6%</ATag></div><Trend :period="period" /></ACard><ACard><h2 class="demo-section-title">服务状态</h2><p class="text-xs text-muted-foreground mb-6">常用应用一览 · 示例</p><div class="space-y-6"><div v-for="service in services" :key="service.slug" class="flex items-center gap-3"><AAvatar :size="40">{{ service.name[0] }}</AAvatar><div class="flex-1"><p class="font-medium mb-1">{{ service.name }}</p><p class="text-xs text-muted-foreground mb-0">{{ service.description }}</p></div><ABadge :status="service.status==='正常'?'success':'warning'" :text="service.status" /></div></div></ACard></div>
      <ACard title="最近执行"><template #extra><AButton type="link" @click="router.push('/tasks')">全部任务 →</AButton></template><ATable :data-source="tasks.slice(0,4)" :columns="[{title:'任务名称',dataIndex:'name'},{title:'应用',dataIndex:'app'},{title:'上次执行',dataIndex:'lastRun'},{title:'耗时',dataIndex:'duration'},{title:'结果',dataIndex:'status',key:'status'}]" row-key="id" :pagination="false" :scroll="{x:600}"><template #bodyCell="{column,record}"><ATag v-if="column.key==='status'" :color="statuses[record.status][1]">{{ statuses[record.status][0] }}</ATag></template></ATable></ACard>
    </template>
    <template v-if="activePath==='/tasks'">
      <ACard><div class="flex justify-between flex-wrap gap-3 mb-5"><AInputSearch v-model:value="query" placeholder="搜索任务或应用…" aria-label="搜索任务" style="max-width:300px" /><ASelect v-model:value="filter" :options="[{label:'全部计划',value:'all'},{label:'已启用',value:'enabled'},{label:'已暂停',value:'paused'}]" aria-label="任务状态筛选" style="width:130px" /></div><ATable :data-source="filteredTasks" :columns="taskColumns" row-key="id" :pagination="{pageSize:5,showTotal:total=>`共 ${total} 个任务`}" :scroll="{x:900}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><p class="font-medium mb-1">{{ record.name }}</p><p class="text-xs text-muted-foreground mb-0">{{ record.description }}</p></template><ATag v-else-if="column.key==='status'" :color="statuses[record.status][1]">{{ statuses[record.status][0] }}</ATag><ASwitch v-else-if="column.key==='enabled'" v-model:checked="record.enabled" :disabled="record.status==='running'" :aria-label="`启用${record.name}`" size="small" /><AButton v-else-if="column.key==='actions'" type="link" size="small" :loading="record.status==='running'" :aria-label="`运行${record.name}`" @click="run(record)">运行</AButton></template></ATable></ACard><AAlert class="mt-5" type="info" show-icon message="本页只模拟任务状态，执行结果会出现在运行日志中；刷新后恢复初始示例。" />
    </template>
    <template v-if="activePath==='/resources'">
      <div class="flex justify-between flex-wrap gap-4 mb-6"><ARadioGroup v-model:value="filter" button-style="solid"><ARadioButton v-for="item in [{label:'全部资源',value:'all'},{label:'图片',value:'image'},{label:'视频',value:'video'},{label:'音频',value:'audio'},{label:'文档',value:'document'}]" :key="item.value" :value="item.value">{{ item.label }}</ARadioButton></ARadioGroup><AInputSearch v-model:value="query" placeholder="搜索资源…" aria-label="搜索资源" style="max-width:260px" /></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-5"><ACard v-for="r in filteredResources" :key="r.id" :body-style="{padding:'18px'}"><template #cover><button class="demo-resource-preview" :aria-label="`预览${r.name}`" @click="preview(r)"><img v-if="r.type==='image'&&r.url" :src="r.url" :alt="r.name" /><span v-else class="text-5xl text-primary">{{ types[r.type][1] }}</span></button></template><div class="flex justify-between items-center gap-3"><button class="font-medium text-left truncate" @click="preview(r)">{{ r.name }}</button><ATag>{{ types[r.type][0] }}</ATag></div><p class="text-xs text-muted-foreground mt-2">{{ r.size }} · {{ r.date }}</p><div class="flex items-center justify-between mt-4"><span class="text-xs text-muted-foreground">{{ r.tag }}</span><AButton type="link" size="small" @click="preview(r)">预览</AButton></div></ACard></div><AEmpty v-if="!filteredResources.length" description="没有匹配的资源" class="my-12" />
    </template>
    <template v-if="activePath==='/logs'"><AAlert type="warning" show-icon message="示例异常：示例上游请求超时，已有缓存仍可使用。" class="mb-6" /><ACard><div class="flex justify-between flex-wrap gap-3 mb-5"><AInputSearch v-model:value="query" placeholder="搜索日志或应用…" aria-label="搜索日志" style="max-width:320px" /><ASelect v-model:value="filter" :options="[{label:'全部级别',value:'all'},{label:'信息',value:'info'},{label:'警告',value:'warn'},{label:'错误',value:'error'}]" aria-label="日志级别筛选" style="width:130px" /></div><ATable :data-source="filteredLogs" :columns="logColumns" row-key="id" :scroll="{x:900}" :pagination="{pageSize:10}"><template #bodyCell="{column,record}"><ATag v-if="column.key==='level'" :color="{info:'processing',warn:'warning',error:'error'}[record.level]">{{ {info:'信息',warn:'警告',error:'错误'}[record.level] }}</ATag></template></ATable></ACard></template>
    <AForm v-if="activePath==='/settings'" :model="settings" layout="vertical" class="max-w-4xl space-y-6" @finish="save"><ACard title="基本信息"><AFormItem label="工作空间名称" name="name" :rules="[{required:true,whitespace:true,message:'请输入工作空间名称'}]"><AInput v-model:value="settings.name" /></AFormItem><AFormItem label="说明"><ATextarea v-model:value="settings.description" :rows="2" /></AFormItem><div class="grid sm:grid-cols-2 gap-5"><AFormItem label="显示时区"><ASelect v-model:value="settings.timezone" :options="['Asia/Shanghai','Asia/Hong_Kong','UTC'].map(value=>({label:value,value}))" /></AFormItem><AFormItem label="日志保留天数"><AInputNumber v-model:value="settings.retention" :min="1" :max="90" class="w-full" /></AFormItem></div></ACard><ACard title="通知偏好"><p class="text-xs text-muted-foreground">演示表单，尚未连接消息发送服务</p><div class="demo-setting-row"><label for="vben-failure">任务失败提醒</label><ASwitch id="vben-failure" v-model:checked="settings.failureNotice" /></div><div class="demo-setting-row"><label for="vben-daily">每日运行摘要</label><ASwitch id="vben-daily" v-model:checked="settings.dailyDigest" /></div></ACard><div class="flex justify-between gap-3 items-center"><span class="text-xs text-muted-foreground">仅保存到当前浏览器</span><AButton type="primary" html-type="submit">保存设置</AButton></div></AForm>
    <footer class="demo-footer"><span>WorkerKit · Vben Admin · 演示数据</span></footer>
    <AModal v-model:open="createOpen" title="新建演示任务" :footer="null"><AForm :model="draft" layout="vertical" class="pt-4" @finish="createTask"><AFormItem label="任务名称" name="name" :rules="[{required:true,whitespace:true,min:2,message:'请输入至少 2 个字的任务名称'}]"><AInput v-model:value="draft.name" placeholder="例如：每日数据同步" /></AFormItem><AFormItem label="所属应用"><ASelect v-model:value="draft.app" :options="['demo-api','demo-content','demo-jobs','demo-storage','demo-reports','demo-assets'].map(value=>({label:value,value}))" /></AFormItem><AFormItem label="执行计划"><ASelect v-model:value="draft.schedule" :options="['每天 09:00','每天 15:45','每 30 分钟','每 6 小时'].map(value=>({label:value,value}))" /></AFormItem><div class="flex justify-end gap-2"><AButton @click="createOpen=false">取消</AButton><AButton type="primary" html-type="submit">创建任务</AButton></div></AForm></AModal>
    <AModal v-model:open="uploadOpen" title="添加本地文件" ok-text="加入资源库" cancel-text="取消" :ok-button-props="{disabled:!files.length}" @ok="upload"><AAlert type="info" message="文件只在当前浏览器预览，不会上传到服务器。" class="my-4" /><AUploadDragger v-model:file-list="files" multiple :before-upload="()=>false"><p class="py-8">拖入文件，或点击选择 · 单个文件不超过 100 MB</p></AUploadDragger></AModal>
    <AModal v-model:open="previewOpen" :title="selected?.name" :footer="null" :width="720" destroy-on-close><template v-if="selected"><img v-if="selected.type==='image'&&selected.url" :src="selected.url" :alt="selected.name" class="w-full max-h-[60vh] object-contain" /><video v-else-if="selected.type==='video'&&selected.url" :src="selected.url" controls preload="metadata" class="w-full" /><audio v-else-if="selected.type==='audio'&&selected.url" :src="selected.url" controls class="w-full my-6" /><AAlert v-else type="info" :message="`文档元数据示例 · ${selected.size} · ${selected.tag}`" /></template></AModal>
  </div>
</template>
